import AES from 'crypto-js/aes';
import encUtf8 from 'crypto-js/enc-utf8';
import { extStorageGet, extStorageSet } from './smit-connect';

// Persistent token cache, ported from adscheck Facebook.js getStorageData /
// updateStorageData. The whole bundle (access_token + fb_dtsg + lsd + the BM
// token) lives AES-encrypted under one key in the extension's
// chrome.storage.local, so it survives page reloads for up to 6h. This is how
// adscheck warms tokens once and lets parallel callers reuse fb_dtsg/lsd without
// re-scraping the page.
//
// The AES key is carried over verbatim from adscheck — it is obfuscation, not
// real secrecy (the key ships in the bundle); the real protection is that the
// data sits in the extension's storage, not the page's.

const STORAGE_KEY = 'adscheck_data';
const AES_KEY = 'pRopertyOf$MIT_123321';
const TTL_MS = 21600000; // 6h, same as adscheck

// One stored bundle. Each token carries the timestamp it was fetched at so we
// can expire it independently (mirrors adscheck token_b.date / token_g.date).
export interface CachedToken {
  access_token: string;
  date: number;
}

export interface StoredData {
  user_id?: string;
  fb_dtsg?: string;
  fb_dtsg_ag?: string;
  lsd?: string;
  user_name?: string;
  // token_b = POWER_EDITOR, token_g = BUSINESS_MANAGER (adscheck naming).
  token_b?: CachedToken;
  token_g?: CachedToken;
}

function encrypt(text: string): string {
  return AES.encrypt(text, AES_KEY).toString();
}

function decrypt(hash: string): string | null {
  try {
    return AES.decrypt(hash, AES_KEY).toString(encUtf8) || null;
  } catch {
    return null;
  }
}

/** Read + decrypt the stored bundle from the extension. null when absent/unreadable. */
export async function getStorageData(): Promise<StoredData | null> {
  const raw = await extStorageGet<string>(STORAGE_KEY);
  if (!raw) return null;
  const json = decrypt(raw);
  if (!json) return null;
  try {
    return JSON.parse(json) as StoredData;
  } catch {
    return null;
  }
}

/** Merge `patch` into the stored bundle and write it back encrypted (best-effort). */
export async function updateStorageData(patch: Partial<StoredData>): Promise<void> {
  const current = (await getStorageData()) ?? {};
  const merged = { ...current, ...patch };
  await extStorageSet({ [STORAGE_KEY]: encrypt(JSON.stringify(merged)) });
}

/** True when a cached token exists and is within the 6h TTL. */
export function isTokenFresh(token: CachedToken | undefined, now: number): boolean {
  return Boolean(token?.access_token && token.date && now - token.date < TTL_MS);
}

/** Expire one stored token (used on auth error) by zeroing its date. */
export async function invalidateStoredToken(which: 'token_b' | 'token_g'): Promise<void> {
  const current = await getStorageData();
  if (!current?.[which]) return;
  await updateStorageData({ [which]: { access_token: '', date: 0 } });
}
