<script setup lang="ts">
import { computed, ref } from 'vue';
import { Button } from '@mf2/shared-ui';
import { AdAccountTable, useAccountList } from '../../account-list';
import { ToolPanel } from '../../tool-actions';
import { PageToolPanel } from '../../page-tool-actions';
import { useAccountSelection } from '../../account-selection';
import { usePageSelection } from '../../page-selection';
import { PageManagerView } from '../../page-manager';
import { BmDataLoadingView } from '../../bm-data-loading';
import { BmActionPanel } from '../../bm-actions';

type ActiveTable = 'adAccounts' | 'pages' | 'bm';

// Resolve the selected ids (owned by account-selection) against the account data
// (owned by account-list) here, where both are available — keeps account-selection
// decoupled from account data. ToolPanel receives the resolved accounts.
const { accounts } = useAccountList();
const { selectedIds } = useAccountSelection();
const { selectedCount: pageSelectedCount } = usePageSelection();
const activeTable = ref<ActiveTable>('adAccounts');
const selectedAccounts = computed(() =>
  accounts.value.filter((a) => selectedIds.value.has(a.id))
);
</script>

<template>
  <div class="flex h-full flex-col gap-4 p-4">
    <div class="flex flex-wrap items-center justify-between gap-3">
      <div>
        <h1 class="text-lg font-bold text-white">Quản lý TKQC</h1>
        <p class="mt-1 text-sm text-white/50">Bảng tài khoản quảng cáo và công cụ thao tác nhanh.</p>
      </div>
    </div>

    <!-- Table 3/4 (left) + tool panel 1/4 (right) -->
    <div class="grid min-h-0 flex-1 grid-cols-4 gap-4">
      <div class="col-span-3 flex min-h-0 flex-col gap-3">
        <div class="flex items-center gap-2">
          <Button
            size="sm"
            :variant="activeTable === 'adAccounts' ? 'default' : 'outline'"
            @click="activeTable = 'adAccounts'"
          >
            Bảng TKQC
          </Button>
          <Button
            size="sm"
            :variant="activeTable === 'pages' ? 'default' : 'outline'"
            @click="activeTable = 'pages'"
          >
            Bảng Page
          </Button>
          <Button
            size="sm"
            :variant="activeTable === 'bm' ? 'default' : 'outline'"
            @click="activeTable = 'bm'"
          >
            Bảng BM
          </Button>
        </div>

        <div class="min-h-0 flex-1">
          <AdAccountTable v-if="activeTable === 'adAccounts'" />
          <PageManagerView v-else-if="activeTable === 'pages'" />
          <BmDataLoadingView v-else />
        </div>
      </div>
      <div class="col-span-1 min-h-0">
        <!-- Tool panel follows the active table: TKQC tools for TKQC, Page tools
             for Page, BM tools for BM. Each panel reads its own selection store. -->
        <ToolPanel v-if="activeTable === 'adAccounts'" :selected-accounts="selectedAccounts" />
        <PageToolPanel v-else-if="activeTable === 'pages'" :selected-count="pageSelectedCount" />
        <BmActionPanel v-else-if="activeTable === 'bm'" />
      </div>
    </div>
  </div>
</template>
