<script setup lang="ts">
import { computed, ref } from 'vue';
import { Icon } from '@mf2/shared-ui/icons';
import { toast } from '@mf2/shared-ui';
import ToolRunnerHeader from './ToolRunnerHeader.vue';
import ToolList from './ToolList.vue';
import { useToolActions } from '../composables/use-tool-actions';
import { provideToolActions } from '../composables/tool-actions-context';
import { useToolRunnerSettings } from '../composables/use-tool-runner-settings';
import { TOOL_RUNNERS } from '../../../api/tools';
import { runBatch } from '../../../api/run-batch';
import { useAccountList, type AdAccount } from '../../account-list';
import { useModeStore } from '../../../stores/mode-store';

const props = defineProps<{ selectedAccounts: AdAccount[] }>();

const mode = useModeStore();
const { accounts, applyPatches } = useAccountList();
const toolActions = useToolActions();
// Provide the TKQC instance to the child ToolList/ToolFunctionForm (they read
// state via injection, so they work for any panel that provides an instance).
provideToolActions(toolActions);
const { enabledFunctions, valuesFor } = toolActions;
const { threads, delayMs } = useToolRunnerSettings();

const selectedCount = computed(() => props.selectedAccounts.length);
const noSelection = ref(false);
const running = ref(false);

// Shared run action — runs EVERY enabled tool (in list order) over the selected
// accounts, one tool after another. Real FB calls go through the extension.
// Each tool reports its own summary toast + one error toast listing failed
// accounts (so every FB error reaches the user, not just the console).
async function onStart() {
  const fns = enabledFunctions.value;
  if (fns.length === 0) return;
  if (selectedCount.value === 0) {
    noSelection.value = true;
    setTimeout(() => (noSelection.value = false), 2000);
    return;
  }

  running.value = true;
  try {
    const nameById = new Map(props.selectedAccounts.map((a) => [a.id, a.name]));
    // Run enabled tools sequentially — each is a full batch over the selection.
    for (const fn of fns) {
      const runner = TOOL_RUNNERS[fn.id];
      if (!runner) {
        toast.warning(`Tool "${fn.label}" chưa được đấu API`);
        continue;
      }

      const values = { ...valuesFor(fn) };
      // Cross-account context: the full account list (e.g. rename sequential mode
      // scans existing names to pick the next free number).
      const ctx = { allAccounts: accounts.value, delayMs: delayMs.value };
      const results = await runBatch(
        props.selectedAccounts,
        (acc, index) => runner(acc, values, index, ctx),
        { threads: threads.value, delayMs: delayMs.value }
      );

      // Push the per-account changes the tool reported (name/status/...) into the
      // list + cache so the table updates without re-fetching from FB.
      const patches = new Map(
        results.filter((r) => r.ok && r.patch).map((r) => [r.accountId, r.patch!])
      );
      applyPatches(patches);

      const failures = results.filter((r) => !r.ok);
      const ok = results.length - failures.length;

      if (ok > 0) toast.success(`Đã chạy ${ok}/${results.length} thành công · ${fn.label}`);
      if (failures.length > 0) {
        // Aggregate every FB error into one toast: "<account name>: <message>".
        const lines = failures
          .map((r) => `• ${nameById.get(r.accountId) ?? r.accountId}: ${r.message}`)
          .join('\n');
        toast.error(`${failures.length}/${results.length} thất bại · ${fn.label}`, {
          description: lines,
          duration: 8000,
        });
      }
    }
  } catch (err) {
    toast.error(`Lỗi: ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    running.value = false;
  }
}
</script>

<template>
  <div class="flex h-full flex-col overflow-hidden rounded-xl border border-white/10 bg-white/[0.02]">
    <div class="space-y-3 border-b border-white/10 px-4 py-3">
      <div>
        <h2 class="text-sm font-semibold text-white">Công cụ thao tác</h2>
        <p class="mt-0.5 text-xs text-white/50">Áp dụng cho {{ selectedCount }} TKQC đã chọn</p>
      </div>
      <ToolRunnerHeader />
    </div>

    <div class="min-h-0 flex-1 overflow-auto px-4 py-4">
      <ToolList :selected-count="selectedCount" />

      <p v-if="noSelection" class="mt-3 text-center text-xs text-amber-300">
        Vui lòng chọn ít nhất 1 TKQC trước khi thao tác.
      </p>
    </div>

    <!-- Shared run button — runs every enabled tool in order -->
    <div class="space-y-2 border-t border-white/10 p-3">
      <button
        type="button"
        :disabled="enabledFunctions.length === 0 || running"
        class="flex w-full items-center justify-center gap-2 rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-blue-500 disabled:cursor-not-allowed disabled:opacity-40"
        @click="onStart"
      >
        <Icon :name="running ? 'loader-2' : 'play'" :size="16" :class="running ? 'animate-spin' : ''" />
        <span>{{
          running
            ? 'Đang chạy...'
            : enabledFunctions.length > 0
              ? `Bắt Đầu (${enabledFunctions.length} tính năng)`
              : 'Bắt Đầu'
        }}</span>
      </button>
      <button
        type="button"
        class="flex w-full items-center justify-center gap-2 rounded-lg bg-emerald-500/90 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-emerald-500"
        @click="mode.setMode('advanced')"
      >
        <span>Chuyển sang chế độ nâng cao</span>
        <Icon name="arrow-right" :size="16" />
      </button>
    </div>
  </div>
</template>
