<script setup lang="ts">
import { Button } from '@mf2/shared-ui';
import { Icon } from '@mf2/shared-ui/icons';
import BmLoadConfigDialog from './BmLoadConfigDialog.vue';
import BmTable from './BmTable.vue';
import { useBmDataLoader } from '../composables/use-bm-data-loader';
import type { BmLoadConfig } from '../types/bm-data-loading.types';

const { rows, isLoadingBase, baseError, activeConfig, hasRows, load, refresh } = useBmDataLoader();

async function submitConfig(config: BmLoadConfig): Promise<void> {
  await load(config);
}
</script>

<template>
  <section class="flex h-full min-h-0 flex-col gap-4">
    <div class="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/10 bg-white/[0.02] p-4">
      <div>
        <p class="text-xs font-semibold uppercase tracking-[0.2em] text-emerald-300">Business Manager</p>
        <h2 class="mt-1 text-lg font-bold text-white">Tải dữ liệu BM</h2>
        <p class="mt-1 text-sm text-white/50">
          Tải base BM trước, sau đó chạy từng nhóm dữ liệu nâng cao theo cấu hình.
        </p>
      </div>
      <div class="flex items-center gap-2">
        <Button v-if="hasRows" type="button" variant="outline" :disabled="isLoadingBase" @click="refresh">
          <Icon name="refresh-cw" :size="15" />
          Tải lại
        </Button>
        <BmLoadConfigDialog @submit="submitConfig" />
      </div>
    </div>

    <p v-if="baseError" class="rounded-lg border border-red-500/20 bg-red-500/10 px-4 py-3 text-sm text-red-300">
      {{ baseError }}
    </p>

    <div v-if="!hasRows && !isLoadingBase" class="flex flex-1 items-center justify-center rounded-xl border border-dashed border-white/10 text-center">
      <div class="max-w-md p-8">
        <Icon name="building-2" :size="32" class="mx-auto text-white/35" />
        <h3 class="mt-3 text-base font-semibold text-white">Chưa có dữ liệu BM</h3>
        <p class="mt-2 text-sm text-white/50">Bấm “Tải dữ liệu BM” để mở cấu hình nguồn và nhóm API.</p>
      </div>
    </div>

    <BmTable v-else :rows="rows" :loading="isLoadingBase" :config="activeConfig" />
  </section>
</template>
