<script setup lang="ts">
import { onMounted } from 'vue';
import { storeToRefs } from 'pinia';
import { Toaster } from '@mf2/shared-ui';
import { useModeStore } from '../stores/mode-store';
import { BasicModeView } from '../features/basic-mode';
import { AdvancedModePlaceholder } from '../features/advanced-mode';
import { getToken } from '../api/fb-token';
import { getBmToken } from '../api/fb-bm-token';
// Federated chunk carries Tailwind utilities (no preflight) so classes render
// correctly when this page is mounted inside the host.
import '../remote-styles.css';

// Mode is a runtime toggle (same URL): basic and advanced share the same business
// logic in composables, only the presentation layer differs.
const { mode } = storeToRefs(useModeStore());

// Load every token kind the tools use up front, in parallel (mirrors adscheck
// getMultiAccessTokenUsed with Promise.all): POWER_EDITOR (page-scraped) +
// BUSINESS_MANAGER (GraphQL). getBmToken internally needs getToken's fb_dtsg/lsd,
// but both share an in-flight lock so the Ads Manager page is scraped only once
// even when racing. Each runner then just passes the token kind it needs — no
// first-use fetch. Failures swallowed (e.g. not logged in); a dead token still
// self-heals via graph()'s auth-error retry.
onMounted(() => {
  void Promise.allSettled([getToken(), getBmToken()]);
});
</script>

<template>
  <BasicModeView v-if="mode === 'basic'" />
  <AdvancedModePlaceholder v-else />

  <!-- Single toast outlet for the remote (tool results, FB errors). -->
  <Toaster position="bottom-center" rich-colors />
</template>
