<script setup lang="ts">
import { computed, ref } from 'vue';
import { Icon } from '@mf2/shared-ui/icons';
import { toast } from '@mf2/shared-ui';
import {
  ToolList,
  ToolRunnerHeader,
  provideToolActions,
} from '../../tool-actions';
import { usePageToolActions } from '../composables/use-page-tool-actions';

// Page tool panel — same UX as the TKQC ToolPanel (flat enable/reorder list +
// schema form + shared "Bắt Đầu"), but acts on selected Pages and is UI-only for
// now: no FB runners wired, so "Bắt Đầu" reports "chưa đấu API" per enabled tool.
const props = defineProps<{ selectedCount: number }>();

const pageToolActions = usePageToolActions();
// Provide THIS panel's instance so the shared ToolList/ToolFunctionForm read the
// Page catalog/state (not TKQC). Each panel provides its own instance.
provideToolActions(pageToolActions);
const { enabledFunctions } = pageToolActions;

const noSelection = ref(false);

// UI-only: no Page runners exist yet. Mirror the TKQC "chưa đấu API" behaviour so
// the panel is fully interactive while the real FB wiring lands in a later phase.
function onStart() {
  const fns = enabledFunctions.value;
  if (fns.length === 0) return;
  if (props.selectedCount === 0) {
    noSelection.value = true;
    setTimeout(() => (noSelection.value = false), 2000);
    return;
  }
  for (const fn of fns) {
    toast.warning(`Tool "${fn.label}" chưa được đấu API`);
  }
}

const enabledCount = computed(() => enabledFunctions.value.length);
</script>

<template>
  <div class="flex h-full flex-col overflow-hidden rounded-xl border border-white/10 bg-white/[0.02]">
    <div class="space-y-3 border-b border-white/10 px-4 py-3">
      <div>
        <h2 class="text-sm font-semibold text-white">Công cụ thao tác Page</h2>
        <p class="mt-0.5 text-xs text-white/50">Áp dụng cho {{ selectedCount }} Page đã chọn</p>
      </div>
      <ToolRunnerHeader />
    </div>

    <div class="min-h-0 flex-1 overflow-auto px-4 py-4">
      <ToolList :selected-count="selectedCount" />

      <p v-if="noSelection" class="mt-3 text-center text-xs text-amber-300">
        Vui lòng chọn ít nhất 1 Page trước khi thao tác.
      </p>
    </div>

    <!-- Shared run button — runs every enabled tool in order (UI-only for now) -->
    <div class="space-y-2 border-t border-white/10 p-3">
      <button
        type="button"
        :disabled="enabledCount === 0"
        class="flex w-full items-center justify-center gap-2 rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-blue-500 disabled:cursor-not-allowed disabled:opacity-40"
        @click="onStart"
      >
        <Icon name="play" :size="16" />
        <span>{{ enabledCount > 0 ? `Bắt Đầu (${enabledCount} tính năng)` : 'Bắt Đầu' }}</span>
      </button>
    </div>
  </div>
</template>
