import { extFetch } from './smit-connect';
import {
  getStorageData,
  invalidateStoredToken,
  isTokenFresh,
  updateStorageData,
} from './fb-token-cache';
import type { FbTokenBundle } from './types';

// Acquire the FB token bundle for the user currently logged in on the browser.
// Ported from Facebook.js getFacebookToken({ type: 'B' }): fetch the Ads Manager
// page through the extension and regex out the tokens from the embedded config.
// Token is for the logged-in user (1 user acts on many ad accounts), NOT
// per-account. Persisted (AES) in the extension storage for 6h via
// fb-token-cache, so it survives reloads (mirrors adscheck); an in-memory copy +
// in-flight lock keep same-session calls cheap.

const ADS_MANAGER_URL = 'https://adsmanager.facebook.com/adsmanager/';

let cached: FbTokenBundle | null = null;
// In-flight fetch shared by concurrent callers so they don't each scrape the Ads
// Manager page. Lets the page warm POWER_EDITOR + BUSINESS_MANAGER in parallel
// (getBmToken internally needs this token) and runBatch run many runners at once,
// all hitting the page at most once.
let inflight: Promise<FbTokenBundle> | null = null;

// Extract the token bundle from a fetched FB page's HTML/JSON text.
function parseTokens(html: string): FbTokenBundle | null {
  // type B (POWER_EDITOR) embeds the access token as __accessToken="...".
  const access_token = html.match(/__accessToken\s*=\s*"([^"]+)"/)?.[1] || null;

  const dtsg = html.match(
    /"DTSGInitData".*?"token":"(.*?)","async_get_token":"(.*?)"/
  );
  const fb_dtsg = dtsg?.[1] || null;
  const fb_dtsg_ag = dtsg?.[2] || undefined;

  const lsd = html.match(/"LSD"(.*?)"token":"(.*?)"}/)?.[2] || null;
  const user_id =
    html.match(/"ACCOUNT_ID":"(\d+)"/)?.[1] ||
    html.match(/"USER_ID":"(\d+)"/)?.[1] ||
    null;

  if (!access_token || !fb_dtsg || !lsd || !user_id) return null;
  return { access_token, fb_dtsg, fb_dtsg_ag, lsd, user_id };
}

// Scrape + parse the token bundle from the Ads Manager page (one network trip,
// plus one redirect follow if FB returns a JS redirect instead of the page).
async function fetchTokenBundle(): Promise<FbTokenBundle> {
  let html = await extFetch(ADS_MANAGER_URL);
  let bundle = parseTokens(html);

  // type B can return a JS redirect instead of the page; if tokens didn't parse,
  // follow the redirect once and re-parse (mirror the reference: key off the
  // parsed token, not a substring scan of the raw HTML).
  if (!bundle) {
    const redirect = html
      .match(/window\.location\.replace\("(.*?)"\)/)?.[1]
      ?.replace(/\\/g, '');
    if (redirect?.startsWith('https')) {
      html = await extFetch(redirect);
      bundle = parseTokens(html);
    }
  }

  if (!bundle) {
    throw new Error(
      'Không lấy được token Facebook. Hãy đăng nhập Facebook trên trình duyệt rồi thử lại.'
    );
  }
  return bundle;
}

// Try the persisted bundle first: reuse the POWER_EDITOR token + fb_dtsg/lsd when
// token_b is still within the 6h TTL. Returns null on miss so we fall back to a
// fresh scrape.
async function loadFromStorage(): Promise<FbTokenBundle | null> {
  const stored = await getStorageData();
  if (!stored || !isTokenFresh(stored.token_b, Date.now())) return null;
  if (!stored.fb_dtsg || !stored.lsd || !stored.user_id) return null;
  return {
    access_token: stored.token_b!.access_token,
    fb_dtsg: stored.fb_dtsg,
    fb_dtsg_ag: stored.fb_dtsg_ag,
    lsd: stored.lsd,
    user_id: stored.user_id,
  };
}

/**
 * Get the FB token bundle. Order: in-memory cache → persisted storage (6h TTL) →
 * fresh scrape. Concurrent callers share one in-flight resolution (so parallel
 * warm-up / batch runs hit the page at most once). Throws a clear Error if tokens
 * can't be parsed (e.g. not logged in / FB markup changed).
 */
export async function getToken(forceRefresh = false): Promise<FbTokenBundle> {
  if (cached && !forceRefresh) return cached;
  if (inflight) return inflight;

  inflight = resolveToken(forceRefresh);
  try {
    cached = await inflight;
    return cached;
  } finally {
    // Clear the in-flight marker whether it resolved or threw, so a failed fetch
    // doesn't permanently poison subsequent calls.
    inflight = null;
  }
}

async function resolveToken(forceRefresh: boolean): Promise<FbTokenBundle> {
  if (!forceRefresh) {
    const fromStorage = await loadFromStorage();
    if (fromStorage) return fromStorage;
  }

  const bundle = await fetchTokenBundle();
  // Persist the fresh bundle (token_b + the shared fb_dtsg/lsd) for 6h.
  await updateStorageData({
    user_id: bundle.user_id,
    fb_dtsg: bundle.fb_dtsg,
    fb_dtsg_ag: bundle.fb_dtsg_ag,
    lsd: bundle.lsd,
    token_b: { access_token: bundle.access_token, date: Date.now() },
  });
  return bundle;
}

/** Drop the cached token (in-memory + persisted) so the next call refetches. */
export async function resetToken(): Promise<void> {
  cached = null;
  await invalidateStoredToken('token_b');
}
