import { graph } from '../fb-graph';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';
import { bareAccountId, wait } from './remove-user-helpers';

// Share an ad account to one or more partner Business Managers, granting a role
// (ported from adscheck App.vue addAgency: POST /act_<id>/agencies with the
// BUSINESS_MANAGER token). Each partner BM is one request; failures are reported
// per-BM. This grants access only — it never revokes the existing partners.
//
// Meta maps each role to a fixed permitted_tasks set. admin gets MANAGE on top
// of the advertiser tasks; analyst is read-only.
const PARTNER_TASKS: Record<string, string[]> = {
  admin: ['ADVERTISE', 'ANALYZE', 'DRAFT', 'MANAGE'],
  advertiser: ['ADVERTISE', 'ANALYZE', 'DRAFT'],
  analyst: ['ANALYZE'],
};

const BM_ID_RE = /^\d{6,}$/;

// Split the textarea on newline/comma/space; keep numeric BM ids (>=6 digits),
// dedupe. Anything else (and duplicates after the first) is reported as skipped
// rather than silently dropped.
function parsePartnerBmIds(value: unknown): { valid: string[]; skipped: string[] } {
  if (typeof value !== 'string') return { valid: [], skipped: [] };
  const seen = new Set<string>();
  const valid: string[] = [];
  const skipped: string[] = [];
  for (const raw of value.split(/[\s,]+/)) {
    const id = raw.trim();
    if (!id) continue;
    if (!BM_ID_RE.test(id) || seen.has(id)) {
      skipped.push(id);
      continue;
    }
    seen.add(id);
    valid.push(id);
  }
  return { valid, skipped };
}

// A share request is OK only when the body confirms it — Graph runs with
// suppress_http_code=1, so HTTP 200 is not proof. Accept an explicit success
// flag or a returned id; anything else is treated as a failure.
function isShareSuccess(res: unknown): boolean {
  if (isGraphError(res)) return false;
  if (typeof res !== 'object' || res === null) return false;
  const value = res as { success?: unknown; id?: unknown };
  return value.success === true || Boolean(value.id);
}

export const sharePartner: ToolRunner = async (account, values, _index, ctx) => {
  // acting_brand_id is the BM that currently holds the ad account. Prefer the
  // structured owner_business id; fall back to the flat `bm` field older loads set.
  const ownerBmId = account.owner_business?.id ?? account.bm ?? null;
  if (!ownerBmId) {
    return { ok: false, message: 'missing_owner_bm_id (TKQC không thuộc BM nào)' };
  }

  const { valid: partnerBmIds, skipped } = parsePartnerBmIds(values.bmIds);
  if (partnerBmIds.length === 0) {
    return { ok: false, message: 'Chưa nhập BM đích hợp lệ (mỗi dòng 1 ID, ≥6 chữ số)' };
  }

  const role = typeof values.role === 'string' && values.role in PARTNER_TASKS ? values.role : 'admin';
  const permitted_tasks = JSON.stringify(PARTNER_TASKS[role]);
  const adId = bareAccountId(account.id);
  const delay = Math.max(0, Math.floor(ctx?.delayMs ?? 0) || 0);

  const success: string[] = [];
  const failed: Array<{ bmId: string; reason: string }> = [];

  for (let i = 0; i < partnerBmIds.length; i += 1) {
    const partnerBmId = partnerBmIds[i] as string;
    const res = await graph<{ success?: boolean; id?: string }>(`/act_${adId}/agencies`, {
      token: 'BUSINESS_MANAGER',
      method: 'POST',
      params: { __cppo: 1 },
      body: {
        accountId: adId,
        acting_brand_id: ownerBmId,
        business: partnerBmId,
        permitted_tasks,
      },
    });

    if (isShareSuccess(res)) success.push(partnerBmId);
    else failed.push({ bmId: partnerBmId, reason: isGraphError(res) ? res.message : 'Không xác nhận được share' });

    // Pause between partner BMs in the same TKQC (UI Delay), like remove-user.
    if (delay > 0 && i < partnerBmIds.length - 1) await wait(delay);
  }

  const parts = [`Share ${success.length}/${partnerBmIds.length} BM`];
  if (skipped.length > 0) parts.push(`bỏ qua ${skipped.length} (rác/trùng)`);
  if (failed.length > 0) parts.push(`lỗi: ${failed.map((f) => `${f.bmId}: ${f.reason}`).join('; ')}`);

  return { ok: failed.length === 0, message: parts.join(' · ') };
};
