<script setup lang="ts">
import { computed, ref } from 'vue';
import { Button, Input, Label } from '@mf2/shared-ui/form-controls';
import { Icon } from '@mf2/shared-ui/icons';
import { toast } from '@mf2/shared-ui/sonner';
import BmActionList from './BmActionList.vue';
import BmManagerDialog from './BmManagerDialog.vue';
import BmAppealLinkDialog from './BmAppealLinkDialog.vue';
import { useBmActions } from '../composables/use-bm-actions';
import { useBmSelection } from '../../bm-data-loading/composables/use-bm-selection';
import { useBmRunner, parseEmails, parseLines } from '../composables/use-bm-runner';

// BM action panel — TKQC-style container: header (selected count + Luồng/Delay),
// the function list, and a shared "Bắt Đầu" button. The panel is data-driven: it
// reads the open function from the catalog, dispatches by id to the runner
// registry, and shows the aggregated summary. A function with requiresBm=false
// (Create BM) runs per session, so the selection UI is hidden for it.
const { selectedBmIds, selectedCount, clear } = useBmSelection();
const { expandedFunction, formValues } = useBmActions();
const { threads, delayMs, isRunning, getRunner, run } = useBmRunner();

const activeRunner = computed(() => getRunner(expandedFunction.value?.id ?? null));
// Viewer functions (kind:'viewer') have no runner — fall back to requiresBm:true.
const requiresBm = computed(() => activeRunner.value?.requiresBm ?? true);
const isViewer = computed(() => expandedFunction.value?.kind === 'viewer');
const isAppeal = computed(() => expandedFunction.value?.kind === 'appeal');

// Viewer dialog state — opened by a viewer function's start button.
const dialogOpen = ref(false);
const dialogFnId = ref<string | null>(null);
const dialogBmId = ref<string | null>(null);

// Appeal-link dialog state — opened by an appeal function's start button. Acts on
// all selected BMs (one result row each), unlike viewer (first BM only).
const appealDialogOpen = ref(false);
const appealBmIds = ref<string[]>([]);

const canStart = computed(() => {
  const fn = expandedFunction.value;
  if (!fn || isRunning.value) return false;
  if (requiresBm.value && selectedCount.value === 0) return false;
  // Viewer / appeal only need a selected BM (checked above) — no form inputs.
  if (fn.kind === 'viewer' || fn.kind === 'appeal') return true;
  // Per-function input checks (the runner needs valid form values to do work).
  if (fn.id === 'share-bm-users') return parseEmails(String(formValues.emails ?? '')).length > 0;
  if (fn.id === 'cancel-pending-invites')
    return formValues.mode !== 'by-email' || parseEmails(String(formValues.emails ?? '')).length > 0;
  if (fn.id === 'create-bm')
    return String(formValues.bmName ?? '').trim().length > 0 && Number(formValues.bmCount) > 0;
  if (fn.id === 'delete-bm') return String(formValues.confirm ?? '') === 'XOA';
  if (fn.id === 'create-adaccount')
    return String(formValues.accName ?? '').trim().length > 0 && Number(formValues.count) > 0;
  if (fn.id === 'claim-adaccount')
    return parseLines(String(formValues.adAccountIds ?? '')).length > 0;
  if (fn.id === 'create-bag') return String(formValues.bagName ?? '').trim().length > 0;
  if (fn.id === 'bag-add-assets')
    return (
      String(formValues.bagId ?? '').trim().length > 0 &&
      parseLines(String(formValues.assetIds ?? '')).length > 0
    );
  if (fn.id === 'assign-assets-to-user')
    return (
      String(formValues.userId ?? '').trim().length > 0 &&
      parseLines(String(formValues.assetIds ?? '')).length > 0
    );
  return true; // leave-bm: only needs a selected BM (checked above)
});

function clampThreads() {
  if (!Number.isFinite(threads.value) || threads.value < 1) threads.value = 1;
}
function clampDelay() {
  if (!Number.isFinite(delayMs.value) || delayMs.value < 0) delayMs.value = 0;
}

async function onStart() {
  if (!canStart.value || !expandedFunction.value) return;

  // Viewer functions open the manage dialog instead of running a runner. The
  // dialog acts on the FIRST selected BM only (list is per-BM); note shown inside.
  if (isViewer.value) {
    dialogFnId.value = expandedFunction.value.id;
    dialogBmId.value = selectedBmIds.value.values().next().value ?? null;
    dialogOpen.value = true;
    return;
  }

  // Appeal functions open the link-output dialog for ALL selected BMs (read-only,
  // one result row each) — no runner, no mutation.
  if (isAppeal.value) {
    appealBmIds.value = [...selectedBmIds.value];
    appealDialogOpen.value = true;
    return;
  }

  isRunning.value = true;
  try {
    // Snapshot formValues so the runner doesn't hold a live reactive ref.
    const res = await run(expandedFunction.value.id, {
      bmIds: [...selectedBmIds.value],
      values: { ...formValues },
    });
    if (res.ok > 0) toast.success(`Thành công ${res.ok}/${res.total}`);
    if (res.warnings.length > 0) {
      toast.warning(`${res.warnings.length}/${res.total} không khớp`, {
        description: res.warnings.join('\n'),
        duration: 8000,
      });
    }
    if (res.errors.length > 0) {
      toast.error(`${res.errors.length}/${res.total} thất bại`, {
        description: res.errors.join('\n'),
        duration: 8000,
      });
    }
  } catch (err) {
    toast.error(`Lỗi: ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    isRunning.value = false;
  }
}
</script>

<template>
  <div class="flex h-full flex-col overflow-hidden rounded-xl border border-white/10 bg-white/[0.02]">
    <div class="space-y-3 border-b border-white/10 px-4 py-3">
      <div>
        <h2 class="text-sm font-semibold text-white">Công cụ thao tác BM</h2>
        <p v-if="requiresBm" class="mt-0.5 text-xs text-white/50">
          Áp dụng cho {{ selectedCount }} BM đã chọn
        </p>
        <p v-else class="mt-0.5 text-xs text-white/50">Tạo BM mới theo phiên đăng nhập</p>
      </div>
      <!-- Run-control inputs (concurrency + delay), same layout as TKQC header -->
      <div class="flex items-center gap-2">
        <div class="flex flex-1 items-center gap-2 rounded-lg border border-border bg-white/[0.02] px-3 py-2">
          <Label for="bm-runner-threads" class="shrink-0 text-xs text-muted-foreground">Luồng</Label>
          <Input
            id="bm-runner-threads"
            v-model.number="threads"
            type="number"
            min="1"
            class="h-7 text-xs"
            @blur="clampThreads"
          />
        </div>
        <div class="flex flex-1 items-center gap-2 rounded-lg border border-border bg-white/[0.02] px-3 py-2">
          <Label for="bm-runner-delay" class="shrink-0 text-xs text-muted-foreground">Delay(ms)</Label>
          <Input
            id="bm-runner-delay"
            v-model.number="delayMs"
            type="number"
            min="0"
            class="h-7 text-xs"
            @blur="clampDelay"
          />
        </div>
      </div>
    </div>

    <div class="min-h-0 flex-1 overflow-auto px-4 py-4">
      <BmActionList :selected-count="selectedCount" />
    </div>

    <!-- Shared run button (acts on the open function) -->
    <div class="space-y-2 border-t border-white/10 p-3">
      <Button :disabled="!canStart" class="w-full" @click="onStart">
        <Icon :name="isRunning ? 'loader-2' : 'play'" :size="16" :class="isRunning ? 'animate-spin' : ''" />
        <span>{{ isRunning ? 'Đang chạy...' : isViewer ? 'Mở danh sách' : isAppeal ? 'Lấy link' : 'Bắt Đầu' }}</span>
      </Button>
      <Button
        v-if="requiresBm"
        variant="outline"
        class="w-full"
        :disabled="selectedCount === 0 || isRunning"
        @click="clear"
      >
        Bỏ chọn ({{ selectedCount }})
      </Button>
    </div>

    <!-- Interactive viewer modal (manage-bag / manage-bm-admins) -->
    <BmManagerDialog
      v-model:open="dialogOpen"
      :function-id="dialogFnId"
      :bm-id="dialogBmId"
    />

    <!-- Appeal-link output dialog (get-appeal-link) -->
    <BmAppealLinkDialog v-model:open="appealDialogOpen" :bm-ids="appealBmIds" />
  </div>
</template>
