import { computed, reactive, ref } from 'vue';
import { BM_TOOL_FUNCTIONS } from '../data/bm-tool-functions';
import type { ToolFunction } from '../../bm-tool-types';

// State for the BM action panel — mirrors use-tool-actions but simpler: the BM
// list is static (no drag-reorder, so no persisted ordering). Module-scoped so
// the list, the expanded form, and the shared "Bắt Đầu" button all agree.
const expandedId = ref<string | null>(null);
// Live form values of the currently-expanded function — the shared run button
// (rendered below the list) reads these to run that function.
const formValues = reactive<Record<string, string | boolean>>({});

const expandedFunction = computed(
  () => BM_TOOL_FUNCTIONS.find((f) => f.id === expandedId.value) ?? null
);

// Seed a form-values object from a function's field defaults.
function seedValues(fn: ToolFunction): Record<string, string | boolean> {
  const values: Record<string, string | boolean> = {};
  for (const field of fn.fields ?? []) {
    values[field.key] =
      field.type === 'switch' ? Boolean(field.default ?? false) : String(field.default ?? '');
  }
  return values;
}

function replaceFormValues(next: Record<string, string | boolean>) {
  for (const key of Object.keys(formValues)) delete formValues[key];
  Object.assign(formValues, next);
}

export function useBmActions() {
  // Accordion: one card open at a time. Opening re-seeds shared form values.
  const toggleExpand = (id: string) => {
    if (expandedId.value === id) {
      expandedId.value = null;
      return;
    }
    expandedId.value = id;
    const fn = BM_TOOL_FUNCTIONS.find((f) => f.id === id);
    if (fn) replaceFormValues(seedValues(fn));
  };

  return {
    functions: BM_TOOL_FUNCTIONS,
    expandedId,
    expandedFunction,
    formValues,
    toggleExpand,
  };
}
